import { loadScriptOnce, basicClean } from "./common";

// Extract text with pdfjs, flatten reading order, add isScanned meta
export async function importPDF(file) {
  await loadScriptOnce("https://unpkg.com/pdfjs-dist@3.11.174/build/pdf.min.js", "pdfjsLib");
  const pdfjsLib = globalThis.pdfjsLib;
  pdfjsLib.GlobalWorkerOptions.workerSrc = "https://unpkg.com/pdfjs-dist@3.11.174/build/pdf.worker.min.js";

  const url = URL.createObjectURL(file);
  const pdf = await pdfjsLib.getDocument({ url }).promise;

  let text = "";
  let totalItems = 0;

  for (let p = 1; p <= pdf.numPages; p++) {
    const page = await pdf.getPage(p);
    const content = await page.getTextContent();
    const items = content.items || [];
    totalItems += items.length;

    // group by y (line), then sort by x
    const lines = new Map();
    items.forEach(it => {
      const y = Math.round(it.transform[5]); // approx baseline y
      const arr = lines.get(y) || [];
      arr.push({ x: it.transform[4], str: it.str });
      lines.set(y, arr);
    });

    const ordered = Array.from(lines.entries())
      .sort((a,b) => b[0]-a[0])  // top to bottom
      .map(([_, arr]) => arr.sort((a,b)=>a.x-b.x).map(x=>x.str).join(" ").trim())
      .filter(Boolean);

    text += ordered.join("\n") + (p < pdf.numPages ? "\n" : "");
  }

  URL.revokeObjectURL(url);

  const isScanned = totalItems < 15; // very few text items → likely scanned
  return { text: basicClean(text), meta: { source: "pdf", pages: pdf.numPages, isScanned } };
}
