import React from "react";
import SectionEditor from "../common/SectionEditor.jsx";
import BulletsEditor from "../common/BulletsEditor.jsx";

/**
 * Experience.jsx
 * - same props you already use: { resume, addItem, removeItem, updateField }
 * - NEW: optional { role } to preselect role examples in the modal
 */
export default function Experience({ resume, addItem, removeItem, updateField, role }) {
  // which experience item has the modal open
  const [openIdx, setOpenIdx] = React.useState(null);

  const openModal = (i) => setOpenIdx(i);
  const closeModal = () => setOpenIdx(null);

  const applyBullets = (i, bullets, mode = "append") => {
    const cur = resume.experience[i]?.bullets || [];
    const cleaned = bullets.filter(Boolean);
    const next = mode === "replace" ? cleaned : [...cur, ...cleaned];
    updateField(`experience.${i}.bullets`, next);
    closeModal();
  };

  return (
    <SectionEditor
      title="Experience"
      items={resume.experience}
      onAdd={() => addItem("experience")}
      onRemove={(id) => removeItem("experience", id)}
      render={(item, i) => (
        <div className="space-y-2">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
            <input
              className="bg-slate-800 border border-white/10 rounded-lg px-3 py-2"
              placeholder="Title (e.g., Software Engineer)"
              value={item.title}
              onChange={(e) => updateField(`experience.${i}.title`, e.target.value)}
            />
            <input
              className="bg-slate-800 border border-white/10 rounded-lg px-3 py-2"
              placeholder="Company"
              value={item.company}
              onChange={(e) => updateField(`experience.${i}.company`, e.target.value)}
            />
          </div>
          <div className="grid grid-cols-2 gap-2">
            <input
              className="bg-slate-800 border border-white/10 rounded-lg px-3 py-2"
              placeholder="Start (e.g., 2023-01)"
              value={item.start}
              onChange={(e) => updateField(`experience.${i}.start`, e.target.value)}
            />
            <input
              className="bg-slate-800 border border-white/10 rounded-lg px-3 py-2"
              placeholder="End (e.g., 2024-06 or Present)"
              value={item.end}
              onChange={(e) => updateField(`experience.${i}.end`, e.target.value)}
            />
          </div>

          {/* Bullets + examples */}
          <div className="flex items-center justify-between">
            <div className="font-medium text-sm">Bullets</div>
            <button
              type="button"
              className="text-xs px-2 py-1 rounded-md bg-white/10 hover:bg-white/15 border border-white/10"
              onClick={() => openModal(i)}
              title="Insert ready-made, metric-first bullets"
            >
              Example Bullets
            </button>
          </div>
          <BulletsEditor
            bullets={item.bullets}
            onChange={(bul) => updateField(`experience.${i}.bullets`, bul)}
          />

          {openIdx === i && (
            <ExampleBulletsModal
              role={role}
              onAppend={(arr) => applyBullets(i, arr, "append")}
              onReplace={(arr) => applyBullets(i, arr, "replace")}
              onClose={closeModal}
            />
          )}
        </div>
      )}
    />
  );
}

/* ---------------------- Modal with curated bullets ---------------------- */

function ExampleBulletsModal({ role, onAppend, onReplace, onClose }) {
  const [selectedRole, setSelectedRole] = React.useState(role || "Frontend Engineer");

  const roles = Object.keys(BULLET_SETS);
  const bullets = BULLET_SETS[selectedRole] || [];

  const append3 = () => onAppend(bullets.slice(0, 3));
  const replace3 = () => onReplace(bullets.slice(0, 3));

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60">
      <div className="w-[min(900px,92vw)] max-h-[80vh] overflow-hidden rounded-xl border border-white/10 bg-slate-900 shadow-xl">
        <div className="px-4 py-3 border-b border-white/10 flex items-center justify-between">
          <div className="font-semibold">Example Bullets (metric-first, ATS-safe)</div>
          <div className="flex items-center gap-2">
            <select
              className="text-sm bg-slate-800 border border-white/10 rounded px-2 py-1"
              value={selectedRole}
              onChange={(e) => setSelectedRole(e.target.value)}
            >
              {roles.map((r) => (
                <option key={r} value={r}>{r}</option>
              ))}
            </select>
            <button
              className="text-xs px-2 py-1 rounded-md bg-white/10 hover:bg-white/15 border border-white/10"
              onClick={onClose}
            >
              Close
            </button>
          </div>
        </div>

        <div className="overflow-y-auto max-h-[calc(80vh-48px)] p-4 space-y-2 text-sm">
          <ul className="list-disc pl-5 space-y-2">
            {bullets.map((b, i) => (
              <li key={i} className="leading-relaxed">{b}</li>
            ))}
          </ul>

        </div>

        <div className="px-4 py-3 border-t border-white/10 flex items-center justify-end gap-2">
          <button
            className="text-xs px-3 py-1.5 rounded bg-white/10 hover:bg-white/15 border border-white/10"
            onClick={append3}
          >
            Append 3 examples
          </button>
          <button
            className="text-xs px-3 py-1.5 rounded bg-emerald-500/90 text-slate-900 font-semibold"
            onClick={replace3}
          >
            Replace with 3 examples
          </button>
        </div>
      </div>
    </div>
  );
}

