import React from "react";

/**
 * Summary.jsx
 * - Shows a textarea for the 2–3 line resume summary
 * - Adds an "Example Summary" button that opens a modal
 * - Modal lists 3 examples for EACH role and lets user "Use this" (insert) or Copy
 *
 * Props supported (flexible to your scaffold):
 *   - resume, updateField, role   // preferred (modular builder style)
 *   - OR value, onChange, role    // fallback if wired that way elsewhere
 */
export default function Summary({ resume, updateField, value, onChange, role }) {
  const summary = typeof value === "string" ? value : (resume?.summary ?? "");
  const setSummary = (v) => {
    if (typeof onChange === "function") onChange(v);
    else if (typeof updateField === "function") updateField("summary", v);
  };

  const [open, setOpen] = React.useState(false);
  const [filter, setFilter] = React.useState("All roles");

  React.useEffect(() => {
    if (role && !open) setFilter("All roles"); // default to all roles as requested
  }, [role, open]);

  return (
    <div className="rounded-xl bg-white/5 border border-white/10 p-4">
      <div className="flex items-center justify-between mb-2">
        <div className="font-semibold">Summary (2–3 lines)</div>
        <button
          type="button"
          className="text-xs px-2 py-1 rounded-md bg-white/10 hover:bg-white/15 border border-white/10"
          onClick={() => setOpen(true)}
        >
          Example Summary
        </button>
      </div>

      <textarea
        rows={3}
        className="w-full bg-slate-800 border border-white/10 rounded-lg px-3 py-2"
        placeholder="Outcome-oriented engineer… (Role + top skills + 1–2 quantified wins)"
        value={summary}
        onChange={(e) => setSummary(e.target.value)}
      />

      {/* Optional helper tip line */}
      <div className="text-xs text-slate-400 mt-2">
        Keep it 35–60 words · include role, 3 core skills/tech, 1–2 metrics. No first-person or fluff.
      </div>

      {open && (
        <ExampleModal
          role={role}
          currentSummary={summary}
          onUse={(text) => {
            setSummary(text);
            setOpen(false);
          }}
          onClose={() => setOpen(false)}
        />
      )}
    </div>
  );
}

/* -------------------- Modal -------------------- */

function ExampleModal({ role, onUse, onClose }) {
  const [query, setQuery] = React.useState("");
  const containerRef = React.useRef(null);

  React.useEffect(() => {
    const onKey = (e) => e.key === "Escape" && onClose();
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, [onClose]);

  React.useEffect(() => {
    const onDown = (e) => {
      if (!containerRef.current) return;
      if (!containerRef.current.contains(e.target)) onClose();
    };
    document.addEventListener("pointerdown", onDown, true);
    return () => document.removeEventListener("pointerdown", onDown, true);
  }, [onClose]);

  const roles = Object.keys(EXAMPLES);
  const filteredRoles = roles.filter((r) => {
    if (!query.trim()) return true;
    return r.toLowerCase().includes(query.toLowerCase());
  });

  const clickCopy = async (text) => {
    try {
      await navigator.clipboard.writeText(text);
      toast("Copied to clipboard");
    } catch {
      toast("Copy failed");
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60">
      <div
        ref={containerRef}
        className="w-[min(960px,92vw)] max-h-[80vh] overflow-hidden rounded-xl border border-white/10 bg-slate-900 shadow-xl"
      >
        <div className="px-4 py-3 border-b border-white/10 flex items-center justify-between">
          <div className="font-semibold">Example Summaries</div>
          <div className="flex items-center gap-2">
            <input
              type="text"
              className="text-sm bg-slate-800 border border-white/10 rounded px-2 py-1"
              placeholder="Filter roles…"
              value={query}
              onChange={(e) => setQuery(e.target.value)}
            />
            <button
              className="text-xs px-2 py-1 rounded-md bg-white/10 hover:bg-white/15 border border-white/10"
              onClick={onClose}
            >
              Close
            </button>
          </div>
        </div>

        <div className="overflow-y-auto max-h-[calc(80vh-48px)] p-4 space-y-5">
          {filteredRoles.length === 0 && (
            <div className="text-sm text-slate-300">No roles match “{query}”.</div>
          )}

          {filteredRoles.map((r) => (
            <div key={r} className="rounded-lg bg-white/5 border border-white/10">
              <div className="px-3 py-2 border-b border-white/10 flex items-center justify-between">
                <div className="font-medium text-sm">
                  {r}
                  {role && r === role ? (
                    <span className="ml-2 text-emerald-300 text-xs align-middle">current role</span>
                  ) : null}
                </div>
              </div>
              <div className="p-3 space-y-3">
                {EXAMPLES[r].map((ex, i) => (
                  <div
                    key={`${r}-${i}`}
                    className="rounded-md bg-slate-800/70 border border-white/10 p-3"
                  >
                    <div className="text-sm leading-relaxed text-slate-100">
                      {ex}
                    </div>
                    <div className="mt-2 flex items-center gap-2">
                      <button
                        className="text-xs px-2 py-1 rounded bg-emerald-500/90 text-slate-900 font-semibold"
                        onClick={() => onUse(ex)}
                      >
                        Use this
                      </button>
                      <button
                        className="text-xs px-2 py-1 rounded bg-white/10 border border-white/10 hover:bg-white/15"
                        onClick={() => clickCopy(ex)}
                      >
                        Copy
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          ))}
        </div>
      </div>
      {/* tiny toast zone */}
      <ToastHost />
    </div>
  );
}

