/* -------------------- Tiny toast (copy feedback) -------------------- */

function ToastHost() {
  const [msg, setMsg] = React.useState("");
  React.useEffect(() => {
    function onToast(e) {
      if (e.detail && typeof e.detail === "string") {
        setMsg(e.detail);
        setTimeout(() => setMsg(""), 1500);
      }
    }
    window.addEventListener("ts_toast", onToast);
    return () => window.removeEventListener("ts_toast", onToast);
  }, []);
  if (!msg) return null;
  return (
    <div className="fixed bottom-4 left-1/2 -translate-x-1/2 z-[100]">
      <div className="px-3 py-1.5 text-sm rounded bg-slate-800 border border-white/10 text-slate-100 shadow">
        {msg}
      </div>
    </div>
  );
}

function toast(text) {
  window.dispatchEvent(new CustomEvent("ts_toast", { detail: text }));
}
