import { loadScriptOnce, basicClean } from "./common";

// Use mammoth.browser to extract plain text from DOCX
export async function importDOCX(file) {
  await loadScriptOnce("https://unpkg.com/mammoth@1.6.0/dist/mammoth.browser.min.js", "mammoth");
  const mammoth = globalThis.mammoth;

  const arrayBuffer = await file.arrayBuffer();
  const { value } = await mammoth.extractRawText({ arrayBuffer });
  return { text: basicClean(value || ""), meta: { source: "docx" } };
}
