// Browser-only helpers shared by all importers

// Load a UMD script once (from a CDN), return the global it defines.
export function loadScriptOnce(src, globalName) {
  return new Promise((resolve, reject) => {
    if (globalName && globalThis[globalName]) return resolve(globalThis[globalName]);
    const existing = document.querySelector(`script[data-once="${src}"]`);
    if (existing) {
      existing.addEventListener("load", () => resolve(globalThis[globalName]));
      existing.addEventListener("error", reject);
      return;
    }
    const s = document.createElement("script");
    s.src = src;
    s.async = true;
    s.defer = true;
    s.dataset.once = src;
    s.onload = () => resolve(globalName ? globalThis[globalName] : true);
    s.onerror = (e) => reject(new Error(`Failed to load: ${src}`));
    document.head.appendChild(s);
  });
}

// ----- Normalization -----
const LIGATURES = { "ﬁ": "fi", "ﬂ": "fl", "ﬀ": "ff", "ﬃ": "ffi", "ﬄ": "ffl" };
const PUNCT = {
  "“": "\"", "”": "\"", "„": "\"", "«": "\"", "»": "\"",
  "‘": "'", "’": "'", "‚": "'",
  "—": "-", "–": "-", "-": "-", "−": "-", "―": "-",
  "…": "...",
};

export function asciiize(str) {
  return str
    .replace(/[ﬁﬂﬀﬃﬄ]/g, m => LIGATURES[m] || m)
    .replace(/[“”„«»‘’‚—–-−―…]/g, m => PUNCT[m] || m);
}

export function normalizeWhitespace(str) {
  return str
    .replace(/\r\n/g, "\n")
    .replace(/[ \t]+\n/g, "\n")
    .replace(/\n{3,}/g, "\n\n")
    .replace(/[ \t]{2,}/g, " ")
    .trim();
}

export function normalizeBullets(str) {
  // Map fancy bullets to • ; later we can convert to '-' for TXT export if needed
  return str.replace(/^[\s]*[▪◦●○•►\-–·*]\s+/gm, m => "• ");
}

export function unwrapHyphenation(str) {
  // Join lines ending with hyphen when next line starts with lowercase/alpha
  return str.replace(/([A-Za-z])-\n([a-z])/g, (_, a, b) => a + b);
}

export function stripHeadersFooters(text) {
  // Heuristic: remove first/last line if it repeats on 2+ pages
  const pages = text.split(/\n\f\n?/); // if we ever mark page breaks
  if (pages.length < 2) return text;
  const firstLines = pages.map(p => (p.split("\n")[0] || "").trim());
  const lastLines  = pages.map(p => (p.trim().split("\n").slice(-1)[0] || "").trim());
  const header = mode(firstLines);
  const footer = mode(lastLines);
  let rebuilt = pages.map(p => {
    let lines = p.split("\n");
    if (header && lines[0] && lines[0].trim() === header) lines.shift();
    if (footer && lines.length && lines[lines.length-1].trim() === footer) lines.pop();
    return lines.join("\n");
  }).join("\n\n");
  return rebuilt;

  function mode(arr) {
    const map = new Map();
    arr.forEach(v => map.set(v, (map.get(v)||0)+1));
    let best = "", cnt = 0;
    for (const [k,v] of map) if (v>cnt && k && k.length<120) { best=k; cnt=v; }
    return cnt>=2 ? best : "";
  }
}

export function basicClean(text) {
  return normalizeWhitespace(
    normalizeBullets(
      unwrapHyphenation(
        asciiize(text)
      )
    )
  );
}

// ----- Section detection -----
const HEADING_RE = /^\s*(summary|professional summary|experience|work experience|employment|projects?|education|skills?|certifications?|awards?|publications?|links?|contact)\s*$/i;
const EMAIL_RE = /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i;
const PHONE_RE = /(?:\+?\d{1,3}[\s.-]?)?(?:\(?\d{3}\)?[\s.-]?){2}\d{4}/;
const URL_RE = /\bhttps?:\/\/[^\s)]+/ig;

export function detectSections(text) {
  // Split into blocks by blank lines
  const lines = text.split("\n");
  const blocks = [];
  let buf = [];
  const flush = () => { if (buf.length) { blocks.push(buf); buf=[]; } };
  for (const ln of lines) {
    if (ln.trim() === "") flush();
    else buf.push(ln);
  }
  flush();

  // Identify headings and group
  const groups = [];
  let current = { title: "header", body: [] };
  for (const b of blocks) {
    const single = b.length <= 2 ? b.join(" ").trim() : "";
    if (HEADING_RE.test(single)) {
      // push previous
      if (current.body.length) groups.push(current);
      current = { title: single.toLowerCase(), body: [] };
    } else {
      current.body.push(...b);
    }
  }
  if (current.body.length) groups.push(current);

  // Build resume
  const resume = { links: [], skills: [], experience: [], projects: [], education: [] };

  // Identity from header group (first group)
  const headerText = (groups.find(g => g.title === "header")?.body || []).join("\n");
  const headerLines = headerText.split("\n").filter(Boolean);
  resume.name  = headerLines[0] && headerLines[0].length <= 80 ? headerLines[0].trim() : "";
  const contacts = headerText;
  const email = contacts.match(EMAIL_RE);
  const phone = contacts.match(PHONE_RE);
  const links = (contacts.match(URL_RE) || []).slice(0, 6);
  if (email) resume.email = email[0];
  if (phone) resume.phone = phone[0];
  if (links.length) resume.links = Array.from(new Set(links));

  // Map helper: parse bullets under a section into records
  function parseBulletedRecords(sectionBody, kind) {
    const arr = [];
    const chunked = [];
    let tmp = [];
    const push = () => { if (tmp.length) { chunked.push(tmp); tmp=[]; } };
    for (const ln of sectionBody) {
      if (/^\s*[•\-*]\s+/.test(ln)) { tmp.push(ln.replace(/^\s*[•\-*]\s+/, "")); }
      else if (ln.trim()==="") { push(); }
      else {
        // start new record header line
        push();
        tmp.push("__HDR__ " + ln.trim());
        push();
      }
    }
    push();
    for (const chunk of chunked) {
      const hdrIndex = chunk.findIndex(x => x.startsWith("__HDR__ "));
      if (hdrIndex >= 0) {
        const hdr = chunk[hdrIndex].replace("__HDR__ ", "");
        const bullets = chunk.slice(hdrIndex + 1);
        if (kind === "experience") {
          arr.push({ id: cryptoId(), title: guessTitle(hdr), company: guessCompany(hdr), bullets });
        } else if (kind === "projects") {
          const m = hdr.match(/\bhttps?:\/\/\S+/);
          arr.push({ id: cryptoId(), name: hdr.replace(/\s*https?:\/\/\S+/, ""), link: m ? m[0] : "", bullets });
        } else if (kind === "education") {
          arr.push({ id: cryptoId(), school: hdr, degree: "", year: (hdr.match(/\b(20\d{2}|19\d{2})\b/)||[])[0] || "" });
        }
      } else {
        // No header, treat as free bullets under one record
        if (chunk.length) {
          arr.push({ id: cryptoId(), bullets: chunk });
        }
      }
    }
    return arr;
  }

  // Fill sections
  for (const g of groups) {
    const t = g.title;
    const body = g.body;
    if (/summary/.test(t)) {
      resume.summary = body.join(" ").trim();
    } else if (/experience|employment/.test(t)) {
      resume.experience = parseBulletedRecords(body, "experience");
    } else if (/projects?/.test(t)) {
      resume.projects = parseBulletedRecords(body, "projects");
    } else if (/education/.test(t)) {
      resume.education = parseBulletedRecords(body, "education");
    } else if (/skills?/.test(t)) {
      // split on commas or bullets
      const raw = body.join("\n");
      resume.skills = raw
        .replace(/^[\s]*[•\-*]\s+/gm, "")
        .split(/[,;\n]+/)
        .map(s => s.trim())
        .filter(Boolean);
    }
  }

  return resume;
}

function guessTitle(hdr) {
  // crude: prefer tokens with Title Case, known tech roles
  const roles = ["engineer","developer","manager","lead","intern","architect","analyst","scientist","devops","sre","designer"];
  const parts = hdr.split(/[—–\-|@•]+/).map(s => s.trim());
  const maybe = parts.find(p => roles.some(r => new RegExp(`\\b${r}\\b`, "i").test(p)));
  return maybe || parts[0] || hdr;
}
function guessCompany(hdr) {
  const parts = hdr.split(/[—–\-|@•]+/).map(s => s.trim());
  return parts[1] || "";
}

export function makeReport(text, resume, meta) {
  const words = (text.match(/\b\w+\b/g) || []).length;
  const bullets = (text.match(/^[\s]*[•\-*]\s+/gm) || []).length;
  const dates = (text.match(/\b(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)\.?\s?\d{4}\b/gi) || []).length
              + (text.match(/\b(19|20)\d{2}\s?(?:–|-|to)\s?(?:Present|Current|(19|20)\d{2})\b/gi) || []).length;
  const sections = ["summary","experience","projects","education","skills"].filter(s => resume[s] && (Array.isArray(resume[s]) ? resume[s].length : resume[s])).length;

  const warnings = [];
  if (meta.isScanned) warnings.push("Looks like a scanned PDF — text quality may be reduced. Prefer DOCX or text PDF.");
  if (/\|.+\|.+\|/.test(text)) warnings.push("Detected table-like content; tables are not preserved in ATS mode.");
  if (/[^\x00-\x7F]/.test(text)) warnings.push("Non-ASCII punctuation normalized for ATS parsers.");
  if (!resume.summary) warnings.push("No Summary detected — consider adding a 2–3 line pitch.");
  if (!resume.skills || resume.skills.length === 0) warnings.push("No Skills section detected — add key tech keywords.");

  return {
    words, sections, bullets, dates,
    warnings,
    fixes: [
      { id: "ascii",  label: "Normalize quotes/dashes/ligatures", applied: true },
      { id: "hyphen", label: "Unwrap hyphenated line breaks",    applied: true },
      { id: "bullets",label: "Unify bullets to •",               applied: true },
      { id: "headers",label: "Remove headers/footers",           applied: false }, // applied only if we detected page breaks
    ],
  };
}

export function cryptoId() {
  try { return crypto.randomUUID(); } catch { return "id-" + Math.random().toString(36).slice(2); }
}
