/** crude tokenizer for JD diff & ATS keyword check */
function tokenize(text = "") {
  return Array.from(
    new Set(
      (text.toLowerCase().match(/[a-z0-9+#.][a-z0-9+.#-]*/g) || []).filter((t) => t.length > 1)
    )
  );
}

const STOP = new Set([
  "and","the","with","for","you","your","are","our","this","that","from","into","their","they","she","he","we",
  "in","on","to","of","as","at","by","an","or","be","is","it","a"
]);

function importantKeywords(text) {
  return tokenize(text).filter((t) => !STOP.has(t)).slice(0, 400);
}

/** naive passive voice & fluff detectors */
const PASSIVE_HINTS = [" was ", " were ", " been ", " being ", " by "];
const FLUFF_PHRASES = [
  "responsible for","worked on","involved in","various","multiple responsibilities",
  "hard-working","team player","result-oriented","fast learner","go-getter"
];

function containsPassive(s="") {
  const t = " " + s.toLowerCase() + " ";
  return PASSIVE_HINTS.some(h => t.includes(h));
}
function containsFluff(s="") {
  const t = s.toLowerCase();
  return FLUFF_PHRASES.some(h => t.includes(h));
}
function countDigits(s="") {
  return (s.match(/[0-9%]/g) || []).length;
}

/** ---- Languages/Hobbies helpers (support old string arrays & new objects) ---- */
function normalizeLanguages(arr) {
  if (!Array.isArray(arr)) return [];
  return arr.map((x) => {
    if (x && typeof x === "object") {
      return { id: x.id || uid(), name: x.name || "", speak: !!x.speak, write: !!x.write, read: !!x.read, listen: !!x.listen };
    }
    // legacy string item
    return { id: uid(), name: String(x || ""), speak: false, write: false, read: false, listen: false };
  });
}
function normalizeHobbies(arr) {
  if (!Array.isArray(arr)) return [];
  return arr.map((x) => (x && typeof x === "object") ? { id: x.id || uid(), name: x.name || "" } : { id: uid(), name: String(x || "") });
}

function languagesToPrintable(arr) {
  // Accept both shapes
  if (!Array.isArray(arr) || arr.length === 0) return "";
  // object → "English (Speak, Write)"; string → "English"
  return arr.map((x) => {
    if (x && typeof x === "object") {
      const flags = [["Speak", x.speak], ["Write", x.write], ["Read", x.read], ["Listen", x.listen]].filter(([,v]) => v).map(([k]) => k);
      return x.name ? (flags.length ? `${x.name} (${flags.join(", ")})` : x.name) : "";
    }
    return String(x || "");
  }).filter(Boolean).join(", ");
}

function hobbiesToPrintable(arr) {
  if (!Array.isArray(arr) || arr.length === 0) return "";
  return arr.map((x) => (x && typeof x === "object") ? (x.name || "") : String(x || "")).filter(Boolean).join(", ");
}


/** ---------- CDN loaders for PDF/DOCX (no npm install needed) ---------- */
function loadScriptOnce(id, src) {
  return new Promise((resolve, reject) => {
    if (document.getElementById(id)) return resolve();
    const s = document.createElement("script");
    s.id = id;
    s.src = src;
    s.async = true;
    s.onload = () => resolve();
    s.onerror = () => reject(new Error("Failed to load " + src));
    document.head.appendChild(s);
  });
}

async function ensurePDFLibs() {
  if (!window.html2canvas) {
    await loadScriptOnce("html2canvas-cdn","https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js");
  }
  if (!(window.jspdf && window.jspdf.jsPDF)) {
    await loadScriptOnce("jspdf-cdn","https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js");
  }
}

async function ensureDOCXLib() {
  if (!window.docx) {
    await loadScriptOnce("docx-cdn","https://unpkg.com/docx@8.5.0/build/index.umd.js");
  }
}

