/** format resume to a clean, ATS-friendly text export */
function formatResumeTXT(r) {
  const lines = [];
  lines.push(`${r.name || "Your Name"}`);
  lines.push(`${r.email || ""}  ${r.phone || ""}`);
  if (r.links?.length) lines.push(r.links.join(" | "));
  lines.push("");

  if (r.summary) {
    lines.push("SUMMARY");
    lines.push(r.summary);
    lines.push("");
  }

  if (r.experience?.length) {
    lines.push("EXPERIENCE");
    r.experience.forEach((x) => {
      lines.push(`${x.title || "Title"} — ${x.company || "Company"}`);
      if (x.start || x.end) lines.push(`${x.start || ""} – ${x.end || "Present"}`);
      (x.bullets || []).filter(Boolean).forEach((b) => lines.push(`• ${b}`));
      lines.push("");
    });
  }

  if (r.projects?.length) {
    lines.push("PROJECTS");
    r.projects.forEach((p) => {
      lines.push(`${p.name || "Project"}${p.link ? " — " + p.link : ""}`);
      (p.bullets || []).filter(Boolean).forEach((b) => lines.push(`• ${b}`));
      lines.push("");
    });
  }

  if (r.education?.length) {
    lines.push("EDUCATION");
    r.education.forEach((e) => {
      lines.push(`${e.school || "School"} — ${e.degree || ""}`);
      if (e.year) lines.push(`${e.year}`);
      lines.push("");
    });
  }

  if (r.skills?.length) {
    lines.push("SKILLS");
    lines.push(r.skills.join(", "));
    lines.push("");
  }

  if (r.languages?.length) {
   lines.push("LANGUAGES");
   lines.push(languagesToPrintable(r.languages));
   lines.push("");
 }

if (r.hobbies?.length) {
   lines.push("HOBBIES / INTERESTS");
   lines.push(hobbiesToPrintable(r.hobbies));
   lines.push("");
 }

  return lines.join("\n");
}

/** filename download helper */
function download(filename, blobOrText, mime) {
  const blob = blobOrText instanceof Blob ? blobOrText : new Blob([blobOrText], { type: mime || "text/plain;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  a.remove();
  URL.revokeObjectURL(url);
}

